			/**
			 * 사업연도와 서비스실행사업에 따른 기관 콤보데이터 필터설정
			 */
			function setCmbInstFilter() {
			    var cmbBizYr = app.lookup("cmbBizYr").value;
			    var cmbSrvcExcn = app.lookup("cmb6").value;
			    var voDsOperInst = app.lookup("dsInst");
			    
			    voDsOperInst.forEachOfUnfilteredRows(function(row) {
			        var yrFilter = false;
			        var noFilter = false;
			        var bizYrArr = row.getValue("BIZ_YR").split('|');
			        var srvcExcnBizNoArr = row.getValue("SRVC_EXCN_BIZ_NO").split('|');
			        
			        for (var idx = 1; idx < bizYrArr.length; idx++) {
			            var bizYr = bizYrArr[idx];
			            if (bizYr == cmbBizYr)
			                yrFilter = true;
			        }
			        
			        for (var idx = 1; idx < srvcExcnBizNoArr.length; idx++) {
			            var srvcExcnBizNo = srvcExcnBizNoArr[idx];
			            if (srvcExcnBizNo == cmbSrvcExcn || cmbSrvcExcn == '')
			                noFilter = true;
			        }
			        
			        if (yrFilter && noFilter)
			            row.setValue("FILTER", 'Y');
			        else
			            row.setValue("FILTER", 'N');
			    });
			    
			    var cmb5 = app.lookup("cmb5");
			    
			    if (cmb5.getItemCount() == 2)
			        cmb5.selectItem(1);
			    else if (!cmb5.getItemByValue(cmb5.value))
			        cmb5.selectItem(0);
			}

