			function onBtnFileSelectClick(e) {
			    var vcGrdList = app.lookup("grdList");
			    var voDsList = app.lookup("dsList");
			    var row = voDsList.getRow(vcGrdList.getSelectedRowIndex());
			    
			    if (row.getValue("ATNC_SE_CD"))
			        var atnc = app.lookup("dsAtnc").findFirstRow("CMMNS_CD_VALUE=='" + row.getValue("ATNC_SE_CD") + "'").getValue("CMMNS_CD_VALUE_NM");
			    if (row.getValue("ATNC_CS_SE_CD"))
			        var atncCs = app.lookup("dsAtncCs").findFirstRow("CMMNS_CD_VALUE=='" + row.getValue("ATNC_CS_SE_CD") + "'").getValue("CMMNS_CD_VALUE_NM");
			    else {
			        alert("출석사유를 먼저 입력하세요.");
			        return false;
			    }
			    
			    var initValue = {
			        name: row.getValue("TRPR_NM"),
			        date: row.getValue("PTCPTN_YMD"),
			        label: atnc,
			        reasonNm: atncCs,
			        SRVC_PVSN_NO: row.getValue("SRVC_PVSN_NO"),
			        CASE_MNG_NO: row.getValue("CASE_MNG_NO"),
			        CASE_MNG_ODRNO: row.getValue("CASE_MNG_ODRNO"),
			        RESRCE_NO: row.getValue("RESRCE_NO")
			    }
			    
			    util.Dialog.open(app, "app/subms/preconmng/atendprecon/atendPopup1", "사유에 대한 증빙서류", 700, 250, function( /*cpr.events.CUIEvent*/ e) {
			        
			        /*
			         * 다이얼로그 close 이벤트 핸들러(닫기 동작시 반환되는 값에 대한 처리)
			         * 다이얼로그가 이미 닫혀진 상태이기 때문에 다이얼로그 관련 이벤트리스너는 발생하지 않습니다.
			         */
			        /**@type cpr.controls.Dialog*/
			        var dialog = e.control;
			        var returnValue = dialog.returnValue;
			        
			        // returnValue 처리
			        returnValue.forEach(function(each) {
			            if (each) {
			                row.setValue("ATFINO", each["ATFINO"]);
			                row.setValue("REAL_FILE_NM", each["REAL_FILE_NM"]);
			                row.setValue("ATCMFL_CL_NM", each["ATCMFL_CL_NM"]);
			                return;
			            }
			        });
			        
			    }, initValue);
			}

